-- ----------------------------------------------- 6. table names stored as data
-- change_history.table_name points at a table; it is not a recorded fact about the business,
-- so it moves with the table. Left behind, restore-from-trash looks for a table that is not
-- there. No row names one of these today, but one can appear before the cutover.
update public.change_history set table_name = 'categories' where table_name = 'bwa_categories';
update public.change_history set table_name = 'category_aliases' where table_name = 'bwa_category_aliases';
update public.change_history set table_name = 'read_cursors' where table_name = 'folder_bookmarks';
update public.change_history set table_name = 'imported_items' where table_name = 'imported_messages';
update public.change_history set table_name = 'document_bank_accounts' where table_name = 'invoice_bank_accounts';
update public.change_history set table_name = 'document_files' where table_name = 'invoice_files';
update public.change_history set table_name = 'document_history' where table_name = 'invoice_history';
update public.change_history set table_name = 'document_line_items' where table_name = 'invoice_line_items';
update public.change_history set table_name = 'document_taxes' where table_name = 'invoice_tax';
update public.change_history set table_name = 'documents' where table_name = 'invoices';

-- The Hub reads payload.document_id (src/lib/data/use-notification-items.ts), so the triggers
-- rewritten in section 4 now emit that key. The rows already written need the same.
update public.notification_events
   set payload = (payload - 'invoice_id') || jsonb_build_object('document_id', payload->'invoice_id')
 where payload ? 'invoice_id';

-- ------------------------------------ 7. tell the panel what is already set up
-- The panel refuses to provision a database holding tables it did not create, and stands that
-- refusal down only once one of its own steps is recorded. A step is recorded only when every
-- table it owns exists, checked at runtime, so the ledger never claims a half step.
create table if not exists public.schema_migrations (
    id text primary key check (length(btrim(id)) > 0),
    applied_at timestamptz not null default now()
);
alter table public.schema_migrations enable row level security;

do $ledger$
declare
    step record;
begin
    for step in
        select * from (values
            ('0001_tenant_settings', array['tenant_settings', 'tenant_settings_history', 'credential_reads']),
            ('0002_channels', array['channels', 'channel_state', 'channel_folders', 'read_cursors', 'ingest_exclusions']),
            ('0003_master_data', array['companies', 'properties', 'property_companies', 'entity_aliases', 'suppliers', 'supplier_bank_accounts', 'categories', 'category_aliases', 'vat_rates']),
            ('0004_documents', array['documents', 'document_files', 'document_history', 'document_line_items', 'document_taxes', 'document_bank_accounts', 'imported_items', 'processing_log', 'pipeline_runs']),
            ('0005_credentials', array['credentials'])
        ) as t(id, tables)
    loop
        if not exists (select 1 from unnest(step.tables) as name
                        where to_regclass('public.' || name) is null) then
            insert into public.schema_migrations (id) values (step.id) on conflict (id) do nothing;
            raise notice 'recorded % as already set up', step.id;
        else
            raise notice 'step % is not complete here; the panel will offer what is missing', step.id;
        end if;
    end loop;
end $ledger$;

commit;

-- PostgREST answers from a cached schema, so until it reloads every request for a new name is
-- a 404. Outside the transaction: a signal, not a change.
notify pgrst, 'reload schema';
